arguments.file_text:
using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    public string Category { get; set; } = string.Empty;

    [Required, MinLength(1, ErrorMessage = "At least one ingredient is required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required, MinLength(1, ErrorMessage = "At least one step is required.")]
    public string Steps { get; set; } = string.Empty;

    public List<int> Ratings { get; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId = 7;
    private readonly Lock _lock = new();

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "Preheat oven to 475°F.\nStretch dough into a 12-inch round.\nSpread crushed tomatoes over dough.\nTear mozzarella and distribute evenly.\nBake for 10–12 minutes until crust is golden.\nTop with fresh basil and a drizzle of olive oil."
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
                Steps = "Cook spaghetti in salted water until al dente.\nCrisp guanciale in a pan over medium heat.\nWhisk eggs with grated pecorino and pepper.\nDrain pasta, reserving some pasta water.\nToss hot pasta with guanciale off heat.\nAdd egg mixture and toss quickly, adding pasta water as needed."
            },
            new()
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCrushed tomatoes\nHeavy cream\nOnion\nGarlic\nGinger",
                Steps = "Marinate chicken in yogurt and spices for 1 hour.\nGrill or broil chicken until charred.\nSauté onion, garlic, and ginger until soft.\nAdd crushed tomatoes and simmer 15 minutes.\nStir in cream and cut chicken pieces.\nSimmer 10 more minutes and serve with rice."
            },
            new()
            {
                Id = 4, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
                Steps = "Brown ground beef in a skillet.\nAdd taco seasoning and water, simmer 5 minutes.\nWarm tortillas in a dry pan.\nAssemble tacos with beef, lettuce, tomato, and cheese.\nTop with sour cream and salsa."
            },
            new()
            {
                Id = 5, Title = "Pad Thai", Category = "Thai",
                Ingredients = "Rice noodles\nShrimp or tofu\nEggs\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar",
                Steps = "Soak rice noodles in warm water for 30 minutes.\nStir-fry shrimp or tofu until cooked, set aside.\nScramble eggs in the same pan.\nAdd drained noodles with fish sauce, tamarind, and sugar.\nToss in bean sprouts and green onions.\nServe with crushed peanuts and lime wedges."
            },
            new()
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
                Steps = "Preheat oven to 425°F and grease ramekins.\nMelt chocolate and butter together.\nWhisk eggs and sugar until thick.\nFold chocolate mixture into eggs.\nAdd flour and vanilla, mix gently.\nPour into ramekins and bake 12–14 minutes.\nInvert onto plates and serve immediately."
            },
        ];
    }

    public IReadOnlyList<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().Order().ToList();
        }
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null && stars is >= 1 and <= 5)
            {
                recipe.Ratings.Add(stars);
            }
        }
    }

    public Recipe Add(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Id = _nextId++;
            _recipes.Add(recipe);
            return recipe;
        }
    }
}

