@page "/"

<PageTitle>RecipeShare — Home</PageTitle>

<h1>🍳 Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in Categories)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h4 class="card-title">
                        <span class="me-2">@GetEmoji(category)</span>@category
                    </h4>
                    <a href="@($"category/{category}")" class="btn btn-outline-primary mt-2">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] public RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories { get; set; } = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private static string GetEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🥡",
        "Desserts" => "🍫",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="list-group mt-3">
        @foreach (var recipe in Recipes)
        {
            <a href="@($"recipe/{recipe.Id}")" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                <span>@recipe.Title</span>
                <span class="badge bg-warning text-dark rounded-pill">
                    @(recipe.AverageRating > 0 ? $"★ {recipe.AverageRating:F1}" : "No ratings")
                </span>
            </a>
        }
    </div>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<RecipeShare.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (Recipe is null)
{
    <p class="text-danger">Recipe not found.</p>
}
else
{
    <h1>@Recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>

    <h3 class="mt-3">Ingredients</h3>
    <ul>
        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <h3>Rating</h3>
    <StarRating RecipeId="Recipe.Id" />

    <div class="mt-4">
        <a href="@($"category/{Recipe.Category}")" class="btn btn-secondary">← Back to @Recipe.Category</a>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] public RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

<div class="d-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-3 text-decoration-none"
                @onclick="() => Rate(star)"
                title="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
            @(star <= _selectedRating ? "★" : "☆")
        </button>
    }

    @if (_submitted)
    {
        <span class="text-success ms-2">Thanks! You rated @_selectedRating star@(_selectedRating > 1 ? "s" : "").</span>
    }

    @if (_averageRating > 0)
    {
        <span class="text-muted ms-2">(Avg: @_averageRating.ToString("F1") from @_totalRatings rating@(_totalRatings > 1 ? "s" : ""))</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public int RecipeId { get; set; }
    [Inject] public RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private bool _submitted;
    private double _averageRating;
    private int _totalRatings;

    protected override void OnInitialized()
    {
        RefreshStats();
    }

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        _selectedRating = stars;
        _submitted = true;
        RefreshStats();
    }

    private void RefreshStats()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            _averageRating = recipe.AverageRating;
            _totalRatings = recipe.Ratings.Count;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> <a href="@($"recipe/{_submittedId}")">View your recipe →</a>
    </div>
}

<EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="SubmitRecipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label class="form-label" for="title">Title</label>
        <InputText id="title" class="form-control" @bind-Value="_model.Title" />
        <ValidationMessage For="() => _model.Title" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="category">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
            <option value="">— Select a category —</option>
            @foreach (var cat in _categories)
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label class="form-label" for="ingredients">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients" />
        <ValidationMessage For="() => _model.Ingredients" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="steps">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_model.Steps" />
        <ValidationMessage For="() => _model.Steps" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    [Inject] public RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe _model = new();
    private IReadOnlyList<string> _categories = [];
    private bool _submitted;
    private int _submittedId;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.Category))
            _model.Category = "Other";

        var added = RecipeService.Add(_model);
        _submittedId = added.Id;
        _submitted = true;
        _model = new();
    }
}

