@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> <a href="@($"recipe/{_submittedId}")">View your recipe →</a>
    </div>
}

<EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="SubmitRecipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label class="form-label" for="title">Title</label>
        <InputText id="title" class="form-control" @bind-Value="_model.Title" />
        <ValidationMessage For="() => _model.Title" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="category">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
            <option value="">— Select a category —</option>
            @foreach (var cat in _categories)
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label class="form-label" for="ingredients">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients" />
        <ValidationMessage For="() => _model.Ingredients" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="steps">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_model.Steps" />
        <ValidationMessage For="() => _model.Steps" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    [Inject] public RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe _model = new();
    private IReadOnlyList<string> _categories = [];
    private bool _submitted;
    private int _submittedId;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.Category))
            _model.Category = "Other";

        var added = RecipeService.Add(_model);
        _submittedId = added.Id;
        _submitted = true;
        _model = new();
    }
}

